const projectionUnavailable = (cause?: unknown) => {
  const error = new PartySearchProjectionUnavailable({
    code: 'party_search_projection_unavailable',
    reason: 'OntOS Core Search projection is temporarily unavailable',
  });
  if (cause !== undefined) {
    Object.defineProperty(error, 'cause', { configurable: true, value: cause });
  }
  return error;
};

const readHandlerUnavailable = (cause: PartySearchProjectionUnavailable) => {
  const error = new ReadHandlerUnavailable({
    code: 'read_handler_unavailable',
    reason: 'Party Search projection is temporarily unavailable',
  });
  Object.defineProperty(error, 'cause', { configurable: true, value: cause });
  return error;
};

const decodePartyRef = (input: CoreSearchResourceRef) =>
  Schema.decodeUnknownEffect(PartyRefSchema)(input).pipe(Effect.mapError(projectionUnavailable));

const decodeCounterpartyRef = (input: CoreSearchResourceRef) =>
  Schema.decodeUnknownEffect(CounterpartyRefSchema)(input).pipe(Effect.mapError(projectionUnavailable));

const mapPartyProjectionHit = Effect.fn('PartiesProvider.mapPartyProjectionHit')(function* mapPartyHit(
  hit: CoreSearchProjectionHit,
) {
  if (hit.subjectRef !== undefined || hit.matchedSubjectRef !== undefined) {
    return yield* projectionUnavailable();
  }
  const canonicalPartyRef = yield* decodePartyRef(hit.ref);
  const matchedPartyRef = hit.matchedRef === undefined ? undefined : yield* decodePartyRef(hit.matchedRef);
  const base = { archived: hit.archived, canonicalPartyRef, title: hit.title };
  return matchedPartyRef === undefined ? base : { ...base, matchedPartyRef };
});

const mapRolePeriod = (facet: NonNullable<CoreSearchProjectionHit['temporalFacets']>[number]) =>
  Schema.decodeUnknownEffect(CurrentCounterpartyRoleSchema)(facet.value).pipe(
    Effect.mapError(projectionUnavailable),
    Effect.map((role) => {
      const base = { role, validFrom: facet.validFrom };
      return facet.validTo === undefined ? base : { ...base, validTo: facet.validTo };
    }),
  );

const mapCounterpartyProjectionHit = Effect.fn('PartiesProvider.mapCounterpartyProjectionHit')(
  function* mapCounterpartyHit(hit: CoreSearchProjectionHit) {
    if (hit.subjectRef === undefined || hit.selectedLegalEntityId === undefined || hit.matchedRef !== undefined) {
      return yield* projectionUnavailable();
    }
    const [counterpartyRef, canonicalPartyRef] = yield* Effect.all(
      [decodeCounterpartyRef(hit.ref), decodePartyRef(hit.subjectRef)],
      { concurrency: 2 },
    );
    const matchedPartyRef =
      hit.matchedSubjectRef === undefined ? undefined : yield* decodePartyRef(hit.matchedSubjectRef);
    const rolePeriods = yield* Effect.forEach(
      (hit.temporalFacets ?? []).filter(({ key }) => key === 'current-role'),
      mapRolePeriod,
      { concurrency: 1 },
    );
    const base = {
      canonicalPartyRef,
      counterpartyRef,
      legalEntity: {
        legalEntityId: hit.selectedLegalEntityId,
        tenantId: counterpartyRef.tenantId,
      },
      partyArchived: hit.archived,
      partyTitle: hit.title,
      rolePeriods,
    };
    return matchedPartyRef === undefined ? base : { ...base, matchedPartyRef };
  },
);

export const makePartySearchProjectionGateway = (
  coreSearch: CoreSearchQueryRuntimePort,
): PartySearchProjectionGatewayPort =>
  Object.freeze({
    searchCounterparties: (input: CounterpartySearchProjectionQuery, scope: OperationalScope) =>
      coreSearch
        .search(
          input.role === undefined
            ? {
                effectiveAt: input.effectiveAt,
                includeArchived: input.includeArchived,
                moduleId: PARTY_REGISTRY_MODULE_ID,
                query: input.query,
                resourceType: 'party.registry.counterparty',
                selectedLegalEntityId: input.legalEntityId,
                tenantId: input.tenantId,
              }
            : {
                effectiveAt: input.effectiveAt,
                facets: [{ key: 'current-role', values: [input.role] }],
                includeArchived: input.includeArchived,
                moduleId: PARTY_REGISTRY_MODULE_ID,
                query: input.query,
                resourceType: 'party.registry.counterparty',
                selectedLegalEntityId: input.legalEntityId,
                tenantId: input.tenantId,
              },
          scope,
        )
        .pipe(
          Effect.flatMap((hits) =>
            Effect.forEach(hits, mapCounterpartyProjectionHit, {
              concurrency: 1,
            }),
          ),
          Effect.mapError(projectionUnavailable),
        ),
    searchParties: (input: PartySearchProjectionQuery, scope: OperationalScope) =>
      coreSearch
        .search(
          {
            includeArchived: input.includeArchived,
            moduleId: PARTY_REGISTRY_MODULE_ID,
            query: input.query,
            resourceType: 'party.registry.party',
            tenantId: input.tenantId,
          },
          scope,
        )
        .pipe(
          Effect.flatMap((hits) => Effect.forEach(hits, mapPartyProjectionHit, { concurrency: 1 })),
          Effect.mapError(projectionUnavailable),
        ),
  });

export const PartySearchProjectionGatewayLive = Layer.effect(
  PartySearchProjectionGateway,
  Effect.gen(function* makePartySearchProjectionGatewayLive() {
    const coreSearch = yield* CoreSearchQueryRuntime;
    return makePartySearchProjectionGateway(coreSearch);
  }),
);

interface CurrentPartyAliasRow {
  readonly aliasPartyId: string;
  readonly canonicalPartyId: string;
  readonly tenantId: string;
}

interface CurrentPartyAliasTraversal {
  readonly ids: ReadonlySet<string>;
  readonly frontier: readonly string[];
}

const loadCurrentPartyAliases = (transaction: ScopedTransactionExecutor, tenantId: string, ids: ReadonlySet<string>) =>
  Stream.paginate<CurrentPartyAliasTraversal, CurrentPartyAliasRow, PartySearchProjectionUnavailable>(
    { ids, frontier: [...ids] },
    (state) =>
      transaction
        .select({
          aliasPartyId: partyAliases.aliasPartyId,
          canonicalPartyId: partyAliases.canonicalPartyId,
          tenantId: partyAliases.tenantId,
        })
        .from(partyAliases)
        .where(
          and(
            eq(partyAliases.tenantId, tenantId),
            or(
              inArray(partyAliases.aliasPartyId, [...state.frontier]),
              inArray(partyAliases.canonicalPartyId, [...state.frontier]),
            ),
          ),
        )
        .pipe(
          Effect.mapError(projectionUnavailable),
          Effect.flatMap((rows) => {
            if (
              rows.some(
                (row) =>
                  row.tenantId !== tenantId ||
                  (!state.ids.has(row.aliasPartyId) && !state.ids.has(row.canonicalPartyId)),
              )
            ) {
              return Effect.fail(projectionUnavailable());
            }
            const frontier = [
              ...new Set(
                rows.flatMap((row) => [row.aliasPartyId, row.canonicalPartyId]).filter((id) => !state.ids.has(id)),
              ),
            ];
            const next =
              frontier.length === 0
                ? Option.none()
                : Option.some({ ids: new Set([...state.ids, ...frontier]), frontier });
            return Effect.succeed<
              readonly [readonly CurrentPartyAliasRow[], Option.Option<CurrentPartyAliasTraversal>]
            >([rows, next]);
          }),
        ),
  ).pipe(
    Stream.runCollect,
    Effect.map((rows) => new Map(rows.map((row) => [row.aliasPartyId, row]))),
  );

const StoredCurrentPartySearchValueSchema = Schema.Struct({
  isCurrent: Schema.Boolean,
  state: Schema.String,
  validFrom: Schema.DateTimeUtcFromDate,
  validTo: Schema.OptionFromNullOr(Schema.DateTimeUtcFromDate),
  value: Schema.String,
});

const encodeCurrentPartySearchValue = (row: typeof StoredCurrentPartySearchValueSchema.Encoded) =>
  Schema.decodeEffect(StoredCurrentPartySearchValueSchema)(row).pipe(
    Effect.flatMap(({ validTo, ...base }) =>
      Schema.encodeEffect(CurrentPartySearchValueSchema)(
        Option.isNone(validTo) ? base : { ...base, validTo: validTo.value },
      ),
    ),
    Effect.mapError(projectionUnavailable),
  );

/** Read only candidate-connected owner rows, in the existing governed Read transaction. */
export const loadCurrentPartySearchEvidence = Effect.fn('PartiesProvider.loadCurrentEvidence')(
  function* loadCurrentEvidence(
    transaction: ScopedTransactionExecutor,
    scope: OperationalScope,
    hits: readonly PartySearchProjectionHit[],
  ): Effect.fn.Return<CurrentPartySearchEvidence, PartySearchProjectionUnavailable> {
    const requested = hits.flatMap((hit) =>
      hit.matchedPartyRef === undefined ? [hit.canonicalPartyRef] : [hit.canonicalPartyRef, hit.matchedPartyRef],
    );
    if (requested.some((ref) => !Schema.is(PartyRefSchema)(ref) || ref.tenantId !== scope.tenantId)) {
      return yield* projectionUnavailable();
    }
    const requestedIds = new Set(requested.map((ref) => ref.resourceId));
    if (requestedIds.size === 0) {
      return { aliases: [], identities: [] };
    }
    // Include current sibling aliases without a tenant-wide scan. The Stream owns each
    // sequential frontier and visited-ID set; no mutable Effect.gen loop state escapes.
    const aliases = yield* loadCurrentPartyAliases(transaction, scope.tenantId, requestedIds);
    const ids = new Set([
      ...requestedIds,
      ...[...aliases.values()].flatMap((row) => [row.aliasPartyId, row.canonicalPartyId]),
    ]);
    const partyIds = [...ids];
    const identities = yield* transaction
      .select({
        archivedAt: parties.archivedAt,
        displayName: parties.currentDisplayName,
        partyId: parties.partyId,
        tenantId: parties.tenantId,
      })
      .from(parties)
      .where(and(eq(parties.tenantId, scope.tenantId), inArray(parties.partyId, partyIds)))
      .pipe(Effect.mapError(projectionUnavailable));
    const identifiers = yield* transaction
      .select({
        isCurrent: partyOfficialIdentifiers.isCurrent,
        partyId: partyOfficialIdentifiers.partyId,
        state: partyOfficialIdentifiers.state,
        tenantId: partyOfficialIdentifiers.tenantId,
        validFrom: partyOfficialIdentifiers.validFrom,
        validTo: partyOfficialIdentifiers.validTo,
        value: partyOfficialIdentifiers.normalizedValue,
      })
      .from(partyOfficialIdentifiers)
      .where(
        and(
          eq(partyOfficialIdentifiers.tenantId, scope.tenantId),
          inArray(partyOfficialIdentifiers.partyId, partyIds),
          eq(partyOfficialIdentifiers.state, 'ACTIVE'),
          eq(partyOfficialIdentifiers.isCurrent, true),
        ),
      )
      .pipe(Effect.mapError(projectionUnavailable));
    // ADDRESS, PERSONAL and BUSINESS_SENSITIVE values never enter the matching snapshot.
    const contacts = yield* transaction
      .select({
        isCurrent: partyContactPoints.isCurrent,
        partyId: partyContactPoints.partyId,
        privacy: partyContactPoints.privacyClassification,
        state: partyContactPoints.state,
        tenantId: partyContactPoints.tenantId,
        type: partyContactPoints.contactPointType,
        validFrom: partyContactPoints.validFrom,
        validTo: partyContactPoints.validTo,
        value: partyContactPoints.normalizedValue,
      })
      .from(partyContactPoints)
      .where(
        and(
          eq(partyContactPoints.tenantId, scope.tenantId),
          inArray(partyContactPoints.partyId, partyIds),
          inArray(partyContactPoints.contactPointType, ['EMAIL', 'PHONE']),
          eq(partyContactPoints.privacyClassification, 'PUBLIC'),
          eq(partyContactPoints.state, 'ACTIVE'),
          eq(partyContactPoints.isCurrent, true),
        ),
      )
      .pipe(Effect.mapError(projectionUnavailable));
    if (
      [...identities, ...identifiers, ...contacts].some(
        (row) => row.tenantId !== scope.tenantId || !ids.has(row.partyId),
      )
    ) {
      return yield* projectionUnavailable();
    }
    const ref = (resourceId: string) =>
      PartyRefSchema.make({
        moduleId: PARTY_REGISTRY_MODULE_ID,
        resourceId,
        resourceType: 'party.registry.party',
        tenantId: scope.tenantId,
      });
    const identifierValues = yield* Effect.forEach(
      identifiers,
      (row) => encodeCurrentPartySearchValue(row).pipe(Effect.map((value) => ({ partyId: row.partyId, value }))),
      { concurrency: 1 },
    );
    const contactValues = yield* Effect.forEach(
      contacts.flatMap((row) => (row.value === null ? [] : [{ ...row, value: row.value }])),
      (row) =>
        encodeCurrentPartySearchValue(row).pipe(
          Effect.map((value) => ({
            partyId: row.partyId,
            value: { ...value, privacy: row.privacy, type: row.type },
          })),
        ),
      { concurrency: 1 },
    );
    return {
      aliases: [...aliases.values()].map((row) => ({
        aliasPartyRef: ref(row.aliasPartyId),
        canonicalPartyRef: ref(row.canonicalPartyId),
      })),
      identities: identities.map((row) => ({
        archived: row.archivedAt !== null,
        contacts: contactValues.filter((contact) => contact.partyId === row.partyId).map(({ value }) => value),
        displayName: row.displayName,
        identifiers: identifierValues
          .filter((identifier) => identifier.partyId === row.partyId)
          .map(({ value }) => value),
        ref: ref(row.partyId),
      })),
    };
  },
);

const EvidenceAuthorityDecisionsSchema = Schema.Array(
  Schema.Struct({
    decision: Schema.Literals(['allowed', 'denied', 'unavailable']),
    key: Schema.String,
  }),
);

/** Source and canonical-target authority are independent; never trust projected match attribution. */
export const authorizeCurrentPartySearchEvidence = Effect.fn('PartiesProvider.authorizeCurrentEvidence')(
  function* authorizeCurrentEvidence(scope: OperationalScope, evidence: CurrentPartySearchEvidence) {
    if (evidence.identities.some(({ ref }) => !Schema.is(PartyRefSchema)(ref) || ref.tenantId !== scope.tenantId)) {
      return yield* projectionUnavailable();
    }
    const resources = evidence.identities.map(({ ref }) => ({
      moduleId: ref.moduleId,
      resourceId: ref.resourceId,
      resourceType: ref.resourceType,
    }));
    const access = yield* ContextAccess;
    if (access.tenantResources === undefined) {
      return yield* projectionUnavailable();
    }
    if (resources.length === 0) {
      return new Set<string>();
    }
    // Party identity is tenant-owned even when this operation has a selected company.
    const decisions = yield* access
      .tenantResources({
        permission: 'read',
        principalId: scope.principalId,
        resources,
        tenantId: scope.tenantId,
      })
      .pipe(
        Effect.mapError(projectionUnavailable),
        Effect.flatMap(Schema.decodeUnknownEffect(EvidenceAuthorityDecisionsSchema)),
        Effect.mapError(projectionUnavailable),
      );
    const keys = resources.map((ref) => `${ref.moduleId}:${ref.resourceType}:${ref.resourceId}`);
    const byKey = new Map(decisions.map(({ decision, key }) => [key, decision]));
    if (
      decisions.length !== keys.length ||
      byKey.size !== keys.length ||
      keys.some((key) => !byKey.has(key)) ||
      decisions.some(({ decision }) => decision === 'unavailable')
    ) {
      return yield* projectionUnavailable();
    }
    return new Set(
      resources.filter((_ref, index) => byKey.get(keys[index] ?? '') === 'allowed').map(({ resourceId }) => resourceId),
    );
  },
);

export const loadPartySearch = (
  gateway: PartySearchProjectionGatewayPort,
  scope: OperationalScope,
  input: PartiesProviderRequest,
  loadCurrentEvidence: CurrentPartySearchEvidenceLoader,
) =>
  gateway
    .searchParties(
      {
        includeArchived: input.includeArchived ?? false,
        query: input.query,
        tenantId: scope.tenantId,
      },
      scope,
    )
    .pipe(
      Effect.flatMap((hits) => {
        const normalized = normalizePartySearchHits(
          {
            includeArchived: input.includeArchived ?? false,
            tenantId: scope.tenantId,
          },
          hits,
        );
        return resolveSearchNormalization(normalized).pipe(
          Effect.flatMap(() => loadCurrentEvidence(hits)),
          Effect.flatMap((evidence) =>
            DateTime.now.pipe(Effect.map((effectiveAt) => ({ evidence, hits, effectiveAt }))),
          ),
        );
      }),
    );

export const finishPartySearch = Effect.fn('PartiesProvider.finishPartySearch')(function* finishCurrentPartySearch(
  input: PartiesProviderRequest,
  scope: OperationalScope,
  loaded: CurrentPartySearchCandidates,
) {
  const authorized = yield* authorizeCurrentPartySearchEvidence(scope, loaded.evidence);
  const current = yield* resolveSearchNormalization(
    rematchCurrentPartySearchHits(
      {
        effectiveAt: loaded.effectiveAt,
        includeArchived: input.includeArchived ?? false,
        query: input.query,
        tenantId: scope.tenantId,
      },
      loaded.hits,
      loaded.evidence,
      authorized,
    ),
  );
  return yield* resolveSearchNormalization(
    normalizePartySearchHits({ includeArchived: input.includeArchived ?? false, tenantId: scope.tenantId }, current),
  );
});

export const partiesRead = defineRead(
  {
    accessKind: 'search',
    entrypoint: partiesEntrypoint,
    evidencePolicy: {
      captureMode: 'metadata_only',
      policyKey: 'party.registry.search.parties.evidence.v1',
    },
    inputSchema: PartiesProviderRequestSchema,
    legalEntityScope: 'optional',
    owningModuleKey: PARTY_REGISTRY_MODULE_ID,
    permissionTarget: 'tenant',
    policies: [],
    readKey: 'party.registry.search.parties',
    resultSchema: PartiesProviderResponseSchema,
    schemaVersion: '1',
  },
  {
    load: (input, context: ReadLoadContext<PartiesSearchServices>) =>
      context.services.load(input).pipe(Effect.mapError(readHandlerUnavailable)),
    finish: (input, context) =>
      finishPartySearch(input, context.scope, context.loaded).pipe(
        Effect.mapError(readHandlerUnavailable),
        Effect.map((result) => ({ evidence: { resultCount: result.length }, result })),
      ),
  },
  Effect.fn('PartiesProvider.partiesRead')(function* makePartySearchServices(transaction, scope: OperationalScope) {
    const gateway = yield* PartySearchProjectionGateway;
    return {
      load: (input: PartiesProviderRequest) =>
        loadPartySearch(gateway, scope, input, (hits) => loadCurrentPartySearchEvidence(transaction, scope, hits)),
    };
  }),
  () => ({ kind: 'tenant', permission: 'read_party_identity' }),
  (result) => result.map(({ ref }) => ref),
);
